import { useLayoutEffect, useRef } from 'react';
import type { ReactNode } from 'react';
import { showFigure } from './figures';
import type { Locale } from './localeQuery';

// Text never shown as a figure: what a person types or picks, and what is not shown at all.
const SKIP = new Set(['INPUT', 'TEXTAREA', 'SELECT', 'OPTION', 'SCRIPT', 'STYLE']);

/**
 * Shows every figure inside it under the user's locale. Figures are worked out and kept as text with a dot
 * (1234.56) everywhere — in the store, the queries, exports and the audit file — so the locale is applied only
 * here, where they are shown: any element whose whole text is a figure has it rewritten (1.234,56 under de),
 * and rewritten again whenever React changes it. Each rewritten text remembers what React wrote, so going back
 * to en restores it.
 */
export function LocaleFigures({ locale, children }: { locale: Locale; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    // text node -> [what React wrote, what is shown]
    const written = new WeakMap<Text, [string, string]>();

    const apply = (node: Text) => {
      const parent = node.parentElement;
      if (!parent || SKIP.has(parent.tagName)) return;
      const now = node.data;
      const seen = written.get(node);
      const original = seen && seen[1] === now ? seen[0] : now;
      // Only a figure that is the element's whole text; a figure among other words is left alone.
      const whole = parent.textContent?.trim() === original.trim() || (seen !== undefined && parent.textContent?.trim() === now.trim());
      const shown = whole ? original.replace(original.trim(), showFigure(original.trim(), locale)) : original;
      if (shown !== original || seen) written.set(node, [original, shown]);
      if (shown !== now) node.data = shown;
    };
    const walk = (node: Node) => {
      if (node.nodeType === Node.TEXT_NODE) {
        apply(node as Text);
        return;
      }
      const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
      for (let t = walker.nextNode(); t; t = walker.nextNode()) apply(t as Text);
    };

    walk(root);
    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (m.type === 'characterData') walk(m.target);
        else {
          m.addedNodes.forEach(walk);
          // A sibling added or removed changes whether its neighbours are an element's whole text.
          walk(m.target);
        }
      }
      // Our own rewrites are observed too; drop them so they do not loop.
      observer.takeRecords();
    });
    observer.observe(root, { subtree: true, childList: true, characterData: true });
    return () => {
      observer.disconnect();
    };
  }, [locale]);

  return <div ref={ref}>{children}</div>;
}
EOF

